# CASO-LIM-025 · metadata sin autofraude
# Bug: LLM se autoetiqueta fraude en metadata
def run_meta(stack):
    return {
        'stack': stack,
        'auto_fraud': stack == 'llm_structured',
        'policy': 'auto_fraud' if stack == 'llm_structured' else 'no_auto_fraud',
    }

print(run_meta('llm_structured'))

